132→// ExtractModifiedFiles extracts modified file paths from raw export JSON transcript bytes.
133→// This is the bytes-based equivalent of ExtractModifiedFilesFromOffset, used by ReadSession.
134→func ExtractModifiedFiles(data []byte) ([]string, error) {
135→	session, err := ParseExportSession(data)
136→	if err != nil {
137→		return nil, err
138→	}
139→	if session == nil {
140→		return nil, nil
141→	}
142→
143→	seen := make(map[string]bool)
144→	var files []string
145→
146→	for _, msg := range session.Messages {
147→		if msg.Info.Role != roleAssistant {
148→			continue
149→		}
150→		for _, part := range msg.Parts {
151→			if part.Type != "tool" || part.State == nil {
152→				continue
153→			}
154→			if !slices.Contains(FileModificationTools, part.Tool) {
155→				continue
156→			}
157→			for _, filePath := range extractFilePaths(part.State) {
158→				if !seen[filePath] {
159→					seen[filePath] = true
160→					files = append(files, filePath)
161→				}
162→			}
163→		}
164→	}
165→
166→	return files, nil
167→}
