236→// CalculateTokenUsage computes token usage from assistant messages starting at the given offset.
237→func (a *OpenCodeAgent) CalculateTokenUsage(transcriptData []byte, fromOffset int) (*agent.TokenUsage, error) {
238→	session, err := ParseExportSession(transcriptData)
239→	if err != nil {
240→		return nil, fmt.Errorf("failed to parse transcript for token usage: %w", err)
241→	}
242→	if session == nil {
243→		return nil, nil //nolint:nilnil // nil usage for empty data is expected
244→	}
245→
246→	usage := &agent.TokenUsage{}
247→	for i := fromOffset; i < len(session.Messages); i++ {
248→		msg := session.Messages[i]
249→		if msg.Info.Role != roleAssistant || msg.Info.Tokens == nil {
250→			continue
251→		}
252→		usage.InputTokens += msg.Info.Tokens.Input
253→		usage.OutputTokens += msg.Info.Tokens.Output
254→		usage.CacheReadTokens += msg.Info.Tokens.Cache.Read
255→		usage.CacheCreationTokens += msg.Info.Tokens.Cache.Write
256→		usage.APICallCount++
257→	}
258→
259→	return usage, nil
260→}
