 14→// TranscriptLine is an alias to the shared transcript.Line type.
 15→type TranscriptLine = transcript.Line
 16→
 17→// Type aliases for internal use.
 18→type (
 19→	assistantMessage = transcript.AssistantMessage
 20→	toolInput        = transcript.ToolInput
 21→)
 22→
 23→// SerializeTranscript converts transcript lines back to JSONL bytes
 24→func SerializeTranscript(lines []TranscriptLine) ([]byte, error) {
 25→	var buf bytes.Buffer
 26→	for _, line := range lines {
 27→		data, err := json.Marshal(line)
 28→		if err != nil {
 29→			return nil, fmt.Errorf("failed to marshal line: %w", err)
 30→		}
 31→		buf.Write(data)
 32→		buf.WriteByte('\n')
 33→	}
 34→	return buf.Bytes(), nil
 35→}
 36→
 37→// ExtractModifiedFiles extracts files modified by tool calls from transcript
 38→func ExtractModifiedFiles(lines []TranscriptLine) []string {
 39→	fileSet := make(map[string]bool)
 40→	var files []string
 41→
 42→	for _, line := range lines {
 43→		if line.Type != "assistant" {
 44→			continue
 45→		}
 46→
 47→		var msg assistantMessage
 48→		if err := json.Unmarshal(line.Message, &msg); err != nil {
 49→			continue
 50→		}
 51→
 52→		for _, block := range msg.Content {
 53→			if block.Type != "tool_use" {
 54→				continue
 55→			}
 56→
 57→			// Check if it's a file modification tool
 58→			isModifyTool := false
 59→			for _, name := range FileModificationTools {
 60→				if block.Name == name {
 61→					isModifyTool = true
 62→					break
 63→				}
 64→			}
 65→
 66→			if !isModifyTool {
 67→				continue
 68→			}
 69→
 70→			var input toolInput
 71→			if err := json.Unmarshal(block.Input, &input); err != nil {
 72→				continue
 73→			}
 74→
 75→			file := input.FilePath
 76→			if file == "" {
 77→				file = input.NotebookPath
 78→			}
 79→
 80→			if file != "" && !fileSet[file] {
 81→				fileSet[file] = true
 82→				files = append(files, file)
 83→			}
 84→		}
 85→	}
 86→
 87→	return files
 88→}
