106→// toolResultBlock represents a tool_result in a user message
107→type toolResultBlock struct {
108→	Type      string `json:"type"`
109→	ToolUseID string `json:"tool_use_id"`
110→}
111→
112→// userMessageWithToolResults represents a user message that may contain tool results
113→type userMessageWithToolResults struct {
114→	Content []toolResultBlock `json:"content"`
115→}
