117→// FindCheckpointUUID finds the UUID of the message containing the tool_result
118→// for the given tool_use_id
119→func FindCheckpointUUID(lines []TranscriptLine, toolUseID string) (string, bool) {
120→	for _, line := range lines {
121→		if line.Type != "user" {
122→			continue
123→		}
124→
125→		var msg userMessageWithToolResults
126→		if err := json.Unmarshal(line.Message, &msg); err != nil {
127→			continue
128→		}
129→
130→		for _, block := range msg.Content {
131→			if block.Type == "tool_result" && block.ToolUseID == toolUseID {
132→				return line.UUID, true
133→			}
134→		}
135→	}
136→	return "", false
137→}
