158→// CalculateTokenUsage calculates token usage from a Factory AI Droid transcript.
159→// Due to streaming, multiple transcript rows may share the same message.id.
160→// We deduplicate by taking the row with the highest output_tokens for each message.id.
161→func CalculateTokenUsage(transcriptLines []TranscriptLine) *agent.TokenUsage {
162→	// Map from message.id to the usage with highest output_tokens
163→	usageByMessageID := make(map[string]messageUsage)
164→
165→	for _, line := range transcriptLines {
166→		if line.Type != "assistant" {
167→			continue
168→		}
169→
170→		var msg messageWithUsage
171→		if err := json.Unmarshal(line.Message, &msg); err != nil {
172→			continue
173→		}
174→
175→		if msg.ID == "" {
176→			continue
177→		}
178→
179→		// Keep the entry with highest output_tokens (final streaming state)
180→		existing, exists := usageByMessageID[msg.ID]
181→		if !exists || msg.Usage.OutputTokens > existing.OutputTokens {
182→			usageByMessageID[msg.ID] = msg.Usage
183→		}
184→	}
185→
186→	// Sum up all unique messages
187→	usage := &agent.TokenUsage{
188→		APICallCount: len(usageByMessageID),
189→	}
190→	for _, u := range usageByMessageID {
191→		usage.InputTokens += u.InputTokens
192→		usage.CacheCreationTokens += u.CacheCreationInputTokens
193→		usage.CacheReadTokens += u.CacheReadInputTokens
194→		usage.OutputTokens += u.OutputTokens
195→	}
196→
197→	return usage
198→}
