  1→package transcript
  2→
  3→import (
  4→	"bufio"
  5→	"bytes"
  6→	"encoding/json"
  7→	"io"
  8→	"strings"
  9→
 10→	"github.com/entireio/cli/cmd/entire/cli/textutil"
 11→)
 12→
 13→// droppedTypes are entry types that carry no parser-relevant data.
 14→var droppedTypes = map[string]bool{
 15→	"progress":              true,
 16→	"file-history-snapshot": true,
 17→	"queue-operation":       true,
 18→	"system":                true,
 19→}
 20→
 21→// CompactOptions provides metadata fields written to every output line.
 22→type CompactOptions struct {
 23→	Agent      string // e.g. "claude-code"
 24→	CLIVersion string // e.g. "0.42.0"
 25→	StartLine  int    // checkpoint_transcript_start (0 = no truncation)
 26→}
 27→
 28→// compactMeta holds pre-computed JSON fragments for fields that are identical
 29→// on every output line, avoiding repeated marshaling.
 30→type compactMeta struct {
 31→	v          json.RawMessage
 32→	agent      json.RawMessage
 33→	cliVersion json.RawMessage
 34→}
 35→
 36→func newCompactMeta(opts CompactOptions) compactMeta {
 37→	return compactMeta{
 38→		v:          mustMarshal(1),
 39→		agent:      mustMarshal(opts.Agent),
 40→		cliVersion: mustMarshal(opts.CLIVersion),
 41→	}
 42→}
 43→
 44→// Compact converts a full.jsonl transcript into the transcript.jsonl format.
 45→//
 46→// The output format puts version, agent, and cli_version on every line,
 47→// flattens the message wrapper, and splits user tool results into separate entries:
 48→//
 49→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user","ts":"...","content":"..."}
 50→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user_tool_result","ts":"...","tool_use_id":"...","result":{...}}
 51→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"assistant","ts":"...","id":"msg_xxx","content":[...]}
 52→func Compact(content []byte, opts CompactOptions) ([]byte, error) {
 53→	truncated := SliceFromLine(content, opts.StartLine)
 54→	if truncated == nil {
 55→		truncated = []byte{}
 56→	}
 57→
 58→	meta := newCompactMeta(opts)
 59→	reader := bufio.NewReader(bytes.NewReader(truncated))
 60→	var result []byte
 61→
 62→	for {
 63→		lineBytes, err := reader.ReadBytes('\n')
 64→		if err != nil && err != io.EOF {
 65→			return nil, err
 66→		}
 67→
 68→		if len(bytes.TrimSpace(lineBytes)) > 0 {
 69→			outputLines := convertLine(lineBytes, meta)
 70→			for _, ol := range outputLines {
 71→				result = append(result, ol...)
 72→				result = append(result, '\n')
 73→			}
 74→		}
 75→
 76→		if err == io.EOF {
 77→			break
 78→		}
 79→	}
 80→
 81→	return result, nil
 82→}
 83→
 84→// userAliases maps transcript type/role values to the canonical "user" kind.
 85→var userAliases = map[string]bool{
 86→	TypeUser: true,
 87→	"human":  true,
 88→}
 89→
 90→// assistantAliases maps transcript type/role values to the canonical "assistant" kind.
 91→var assistantAliases = map[string]bool{
 92→	TypeAssistant: true,
 93→	"gemini":      true,
 94→}
 95→
 96→// normalizeKind returns the canonical entry kind ("user" or "assistant") for a
 97→// transcript line. It checks the "type" field, then falls back to "role".
 98→// Returns "" for unrecognised or dropped entries.
 99→func normalizeKind(raw map[string]json.RawMessage) string {
100→	kind := unquote(raw["type"])
101→	if kind == "" {
102→		kind = unquote(raw["role"])
103→	}
104→
105→	if droppedTypes[kind] {
106→		return ""
107→	}
108→	if userAliases[kind] {
109→		return TypeUser
110→	}
111→	if assistantAliases[kind] {
112→		return TypeAssistant
113→	}
114→	return ""
115→}
116→
117→// unwrapEnvelope handles envelope formats where the actual message is nested.
118→// Factory AI Droid uses {"type":"message","message":{"role":"user","content":...}}.
119→// If the line is an envelope, it promotes inner fields (role, content) to the top
120→// level and carries over outer fields (timestamp, id) so converters see a flat structure.
121→// Otherwise it returns raw unchanged.
122→func unwrapEnvelope(raw map[string]json.RawMessage) map[string]json.RawMessage {
